"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[5656],{2678(e){e.exports=JSON.parse('{"title":"AI\ub294 \ube0c\ub77c\uc6b0\uc800\ub97c \uc5c6\uc568 \uc218\ub3c4 \uc788\ub2e4.","date":"2025-04-09","coverUrl":"/kudzu-based-bench/assets/notion/3b838eaf753f1ee6.png","html":"<h2 data-notion-block-id=\\"1cbe548d-8a8e-8093-be49-d87e7e1e2c8b\\" id=\\"1cbe548d-8a8e-8093-be49-d87e7e1e2c8b\\">AI\ub294 \ube0c\ub77c\uc6b0\uc800\ub97c \uc5c6\uc568 \uc218\ub3c4 \uc788\ub2e4.</h2><a href=\\"https://www.youtube.com/watch?v=pznpsgZqlGQ&#x26;list=PL6kQg8bP1Ji48T7tM-ScCNm_IfrEtce0d&#x26;index=7\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=pznpsgZqlGQ&#x26;list=PL6kQg8bP1Ji48T7tM-ScCNm_IfrEtce0d&#x26;index=7</a><p data-notion-block-id=\\"1cee548d-8a8e-80d6-86ba-c22451aeb7d8\\">\uacfc\uac70\uc640 \ud604\uc7ac \uc6f9\uc758 \ubaa8\uc2b5, \uadf8\ub9ac\uace0 AI\uac00 \ud604\uc7ac\uc758 \uc6f9 \ud615\ud0dc\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \ubbf8\uce60 \uc218 \uc788\ub294\uc9c0\uc5d0 \ub300\ud55c \ud765\ubbf8\ub85c\uc6b4 \ubc1c\ud45c\uc785\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \ubc1c\ud45c\uc5d0 \ub098\uc624\uc9c0\ub294 \uc54a\uc558\uc9c0\ub9cc, \ubc1c\ud45c\uc758 \ub0b4\uc6a9\uc740 \uc55e\uc73c\ub85c \uc6b0\ub9ac\uac00 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud574\uc57c \ud560 \\"\uae30\ubcf8\uae30\\"\uc758 \uc815\uc758\uc5d0 \ub300\ud574 \ub2e4\uc2dc \ud55c\ubc88 \uace0\ubbfc\ud558\uac8c \ub9cc\ub4e7\ub2c8\ub2e4. \ud604\uc7ac\ub294 HTML, CSS, JS\ub97c \ube44\ub86f\ud55c \uae30\uc220\uacfc \ube0c\ub77c\uc6b0\uc800 \ud658\uacbd\uc5d0 \ub300\ud55c \uae4a\uc774 \uc788\ub294 \uc774\ud574\uac00 \ud504\ub860\ud2b8\uc5d4\ub4dc\uc758 \ud575\uc2ec \uc5ed\ub7c9\uc73c\ub85c \uc5ec\uaca8\uc9c0\uc9c0\ub9cc, \uc6f9\uc758 \uadfc\ubcf8\uc801\uc778 \ubcc0\ud654\ub294 \uc774\ub7ec\ud55c \uae30\ubcf8 \uc5ed\ub7c9\uc758 \uc7ac\uc815\uc758\ub97c \uc694\uad6c\ud560 \uc218\ub3c4 \uc788\uaca0\ub2e4\ub294 \uc0dd\uac01\uc774 \ub4ed\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1cbe548d-8a8e-80b2-bad0-de06c80a87f6\\" id=\\"1cbe548d-8a8e-80b2-bad0-de06c80a87f6\\">React\uc5d0\uc11c SPA\uac00 \ubb50\uae38\ub798</h2><a href=\\"https://reacttraining.com/blog/react-architecture-spa-ssr-rsc\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reacttraining.com/blog/react-architecture-spa-ssr-rsc</a><p data-notion-block-id=\\"1cee548d-8a8e-8012-99ed-c3a1f5f80585\\">SPA\uc640 SSR\uc758 \uac1c\ub150, \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uc18c\uac1c, (\uc8fc\ub85c Server Components\uc5d0 \uad00\ud55c) \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \ube44\uad50\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ubb3c\ub860 SPA\uac00 \uc815\ud655\ud558\uac8c \ubb34\uc5c7\uc778\uac00\uc694?\uc5d0 \ub300\ud55c \uc815\uc758\ub294 \uc57d\uac04\uc529 \ub2e4\ub97c \uc218 \uc788\uc9c0\ub9cc, \uae00\uc5d0\uc11c \uc798 \uc124\uba85\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub354 \uae4a\uac8c, \uadf8\ub9ac\uace0 JS\ub97c \uc544\uc6b0\ub974\ub294 SPA\uc640 \uad00\ub828\ub41c \uac1c\ub150\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc740 <a href=\\"https://jakelazaroff.com/words/whats-a-single-page-app/\\">SPA\ub294 \ubb34\uc5c7\uc778\uac00?</a> \uae00\uc744 \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"1cee548d-8a8e-805e-8edb-f515bf861750\\" id=\\"1cee548d-8a8e-805e-8edb-f515bf861750\\">\ud06c\ub86c\uc758 \uc774\ubbf8\uc9c0 \uc694\uccad \uc21c\uc11c\ub294 \uc5b4\ub5bb\uac8c \uacb0\uc815\ub418\ub294\uac00</h2><a href=\\"https://www.debugbear.com/blog/chrome-image-request-prioritization\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.debugbear.com/blog/chrome-image-request-prioritization</a><p data-notion-block-id=\\"1cee548d-8a8e-8075-a2c3-d5921592ab9c\\">Chrome\uc774 \uc774\ubbf8\uc9c0\uc758 \uc6b0\uc120\uc21c\uc704\ub97c \uc5b4\ub5bb\uac8c \ucc45\uc815\ud558\ub294\uc9c0\uc5d0 \ub300\ud574 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \uc790\uc6d0\uc740 \uc5b4\ub5bb\uac8c \ubc1b\uc544\uc624\ub294\uc9c0 \uc54c\uace0 \uc2f6\uc73c\uc2dc\ub2e4\uba74 <a href=\\"https://ones-to-watch.ethansup.net/news/post/150e548d-8a8e-80c3-9a65-d76db36a4789#152e548d-8a8e-80c6-97aa-c05c29dca568\\">\ube0c\ub77c\uc6b0\uc800\uc640 \ub85c\ub529 \ub9e4\ucee4\ub2c8\uc998</a>\uc774\ub098 web.dev\uc758 <a href=\\"https://web.dev/articles/fetch-priority\\">\uc694\uccad \uc6b0\uc120\uc21c\uc704 \ubb38\uc11c</a>\ub97c \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"1cee548d-8a8e-80f6-a042-e6b45d4eb7d1\\" id=\\"1cee548d-8a8e-80f6-a042-e6b45d4eb7d1\\">React Context \uc815\ub9d0 \uc0ac\uc6a9\ud574\uc57c \ud558\ub098\uc694?</h2><a href=\\"https://blog.codeminer42.com/you-are-using-react-context-wrong/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.codeminer42.com/you-are-using-react-context-wrong/</a><p data-notion-block-id=\\"1cee548d-8a8e-805a-b553-df61549f6275\\"><a href=\\"https://blog.isquaredsoftware.com/2021/01/context-redux-differences/#is-context-a-state-management-tool\\">Context API\uac00 \uc0c1\ud0dc \uad00\ub9ac \ub3c4\uad6c\uac00 \uc544\ub2cc \uc774\uc720</a>\uc5d0\uc11c\ub3c4 \ub9d0\ud558\ub4ef\uc774, Context API\ub294 DI \ud615\ud0dc(\uc644\uc804\ud55c Dependency Injection\uc740 \uc544\ub2d8)\ub97c \ud558\ub294 low level API\ub85c\uc11c \uc791\ub3d9\ud558\uc9c0\ub9cc, \uc0c1\ud0dc \uad00\ub9ac \ub3c4\uad6c\ucc98\ub7fc \uc0ac\uc6a9\ud574\uc11c \uc798\ubabb\ub41c \ub3d9\uc791\uc774 \ubc1c\uc0dd\ud558\ub294 \uacbd\uc6b0\ub97c \uc2ec\uc2ec\uce58 \uc54a\uac8c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 Context API + <code>useState()</code>\ub85c \uc0c1\ud0dc\uad00\ub9ac\ud574\uc57c \ud560 \ub54c \uc8fc\uc758\ud560 \ubd80\ubd84\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ud639\uc740 Context API \uae30\ubc18 \uac00\ubcbc\uc6b4 \uc0c1\ud0dc \uad00\ub9ac \ub3c4\uad6c\ub97c \uc6d0\ud55c\ub2e4\uba74 <a href=\\"https://blog.isquaredsoftware.com/2020/05/blogged-answers-a-mostly-complete-guide-to-react-rendering-behavior/#context-selectors\\"><code>use-context-selector</code></a> \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uace0\ub824\ud574\ubcf4\uc138\uc694.</p><h2 data-notion-block-id=\\"1cbe548d-8a8e-801b-ae61-d3169a4796b3\\" id=\\"1cbe548d-8a8e-801b-ae61-d3169a4796b3\\">CSS-in-JS is sunsetting.</h2><a href=\\"https://fullystacked.net/css-in-js-still-a-thing/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://fullystacked.net/css-in-js-still-a-thing/</a><p data-notion-block-id=\\"1cbe548d-8a8e-8019-a831-c80d2549ae90\\"><code>styled-components</code>\ub294 \uad00\ub9ac \ubaa8\ub4dc\ub85c \ubcc0\uacbd\ub418\uc5c8\uace0, CSS-in-JS\uc758 \uc778\uae30\ub294 utility CSS(tailiwindCSS)\uac00 \uac00\uc838\uac00\ubc84\ub838\uc2b5\ub2c8\ub2e4. \uadf8\ub9ac\uace0 Runtime CSS-in-JS\uc758 \ub300\uccb4\ub85c Compile-time CSS-in-JS\uac00 \ub9ce\uc774 \ub098\uc654\uc9c0\ub9cc, \uc778\uae30\ub97c \ub418\ucc3e\uc544\uc624\uc9c0 \ubabb\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc774 \ud574\uacb0\ucc45\uc774\ub098 \uc778\uae30\uac00 \ub5a8\uc5b4\uc9c4 \ud655\uc2e4\ud55c \uc774\uc720\ub97c \uc81c\uc2dc\ud558\uc9c0 \uc54a\uc9c0\ub9cc, \uc778\uae30\uac00 \ub5a8\uc5b4\uc9c4 \ud604\uc0c1\uc740 \uc9c0\ucf1c\ubd10\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"1cee548d-8a8e-80ca-89cb-c869bde336ad\\" id=\\"1cee548d-8a8e-80ca-89cb-c869bde336ad\\">\ud750\ub9bf\ud55c \ub300\uccb4 \uc774\ubbf8\uc9c0 \ub9cc\ub4e4\uae30</h2><a href=\\"https://leanrada.com/notes/css-only-lqip/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://leanrada.com/notes/css-only-lqip/</a><p data-notion-block-id=\\"1cee548d-8a8e-80b7-8865-e6ac1ddc6cec\\">LQIP(Low Quailty Image Placeholder)\ub97c \uad6c\ud604\ud558\ub294 \uc5ec\ub7ec \uae30\uc220\uc744 \ucc3e\uc544\ubcf4\uace0, \uc21c\uc218 CSS\ub85c \uad6c\ud604 \ud574\ubcf4\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Lazy image\ub97c \uad6c\ud604\ud558\ub294\ub370\uc5d0 \ub354 \uc88b\uc740 UX\ub97c \uc81c\uacf5\ud560 \uc218 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"1cbe548d-8a8e-804b-91cd-f0cdbeaba5bf\\" id=\\"1cbe548d-8a8e-804b-91cd-f0cdbeaba5bf\\">\ud5e4\ub354\ub97c \ubbff\uc9c0 \ub9c8\uc138\uc694.</h2><a href=\\"https://macarthur.me/posts/forbidden-request-headers/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://macarthur.me/posts/forbidden-request-headers/</a><p data-notion-block-id=\\"1cee548d-8a8e-802b-b948-e11c32cac71f\\">\ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c JS\ub85c \uc218\uc815\ud560 \uc218 \uc5c6\ub294 \ud5e4\ub354(forbidden request header)\ub97c \uc18c\uac1c\ud558\uace0, \uc0ac\uc6a9\uc758 \uc7a5\ub2e8\uc810\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1cbe548d-8a8e-80fb-b29a-cb52af30092f\\" id=\\"1cbe548d-8a8e-80fb-b29a-cb52af30092f\\">\ube44\ub3d9\uae30 \ucf54\ub4dc\uc5d0\uc11c \ub3d9\uae30 \ucf54\ub4dc\ub97c \uc2e4\ud589\ud560 \uc218 \uc788\ub2e4. \uadf8 \ubc18\ub300\ub294?</h2><a href=\\"https://2ality.com/2025/03/sync-await.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2ality.com/2025/03/sync-await.html</a><p data-notion-block-id=\\"1cbe548d-8a8e-80bc-8a86-c66e502d091c\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/1ade548d-8a8e-8033-98a3-d8ad96c244aa#1ade548d-8a8e-8092-b045-d49ba735576c\\">\ub3d9\uae30\uc640 \ube44\ub3d9\uae30 \uadf8 \uc0ac\uc774 \uc5b4\ub518\uac00</a> \uae00\uc5d0\uc11c\ub294 \ube44\ub3d9\uae30 \ucf54\ub4dc\uc5d0\uc11c \ub3d9\uae30 \ucf54\ub4dc\ub97c \ud638\ucd9c\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 quansync\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc774 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0\uc11c\ub3c4 \ub3d9\uae30 \ucf54\ub4dc\uc5d0\uc11c \ube44\ub3d9\uae30 \ucf54\ub4dc\ub97c \uc2e4\ud589\ud558\ub294 \uac83\uc740 \ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \ub3d9\uae30 await\uac00 \uc788\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ub420 \uac83\uc778\uc9c0, \uc65c \uc5c6\uc744 \uc608\uc815\uc778\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1cbe548d-8a8e-8052-b26c-e38356e3d2d3\\" id=\\"1cbe548d-8a8e-8052-b26c-e38356e3d2d3\\">CSS override\ub97c \ubaa8-\ub2e8\ud558\uac8c \ud558\ub294 \ubc95</h2><a href=\\"https://cloudfour.com/thinks/cowardly-defaults-and-courageous-overrides-with-modern-css/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://cloudfour.com/thinks/cowardly-defaults-and-courageous-overrides-with-modern-css/</a><p data-notion-block-id=\\"1cbe548d-8a8e-80e0-a792-c4f669a0550e\\">\uc608\uc804\uc758 CSS override\ud558\ub294 \ubc29\ubc95\uacfc \ucd5c\uadfc CSS \ubb38\ubc95\uc744 \uc0ac\uc6a9\ud574\uc11c override\ud558\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <code>:where()</code>\uacfc <code>@layer</code>\ub294 \ucd5c\uc2e0 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ubaa8\ub450 \uc9c0\uc6d0\ud558\uc9c0\ub9cc, \ub808\uac70\uc2dc \ube0c\ub77c\uc6b0\uc800\ub97c \uc9c0\uc6d0\ud574\uc57c \ud558\ub294 \uacbd\uc6b0 \uc870\uc2ec\ud574\uc11c \uc0ac\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1cee548d-8a8e-8065-832e-dffb565e4291\\" id=\\"1cee548d-8a8e-8065-832e-dffb565e4291\\">Node.js\uc5d0\uc11c \ud30c\uc77c\uc744 \uc81c\uacf5\ud560 \ub54c \uc8fc\uc758\ud574\uc57c \ud558\ub294 \ucde8\uc57d\uc810</h2><a href=\\"https://www.nodejs-security.com/blog/nodejs-api-security-vulnerabilities-path-traversal-files-bucket-server/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nodejs-security.com/blog/nodejs-api-security-vulnerabilities-path-traversal-files-bucket-server/</a><p data-notion-block-id=\\"1c9e548d-8a8e-80c1-92fe-c3df137f6955\\">\ud30c\uc77c \uc2dc\uc2a4\ud15c\uc744 \uac80\uc99d\ud558\uc9c0 \uc54a\uace0 \uc9c1\uc811 \ub123\uc5c8\uc744 \uacbd\uc6b0 \ub2e4\ub978 \ub85c\uceec \ud30c\uc77c\uc5d0 \uc811\uadfc\ud560 \uc218 \uc788\ub294 \ucde8\uc57d\uc810\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1cbe548d-8a8e-807d-8a81-ff873593b361\\" id=\\"1cbe548d-8a8e-807d-8a81-ff873593b361\\">\uc801\uc751\ud615 \ube44\ub514\uc624 \uc2a4\ud2b8\ub9ac\ubc0d \uc785\ubb38\ud558\uae30</h2><a href=\\"https://www.smashingmagazine.com/2025/03/adaptive-video-streaming-dashjs-react/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2025/03/adaptive-video-streaming-dashjs-react/</a><p data-notion-block-id=\\"1cbe548d-8a8e-8085-b05a-f19227dcbdce\\">\ube44\ub514\uc624\ub97c \uc800\uc0ac\uc591 \uae30\uae30\uc5d0\uc11c\ub3c4 (\uadf8\ub098\ub9c8) \uc6d0\ud65c\ud558\uac8c \uc7ac\uc0dd\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uc801\uc751\ud615 \ube44\ud2b8\ub808\uc774\ud2b8 \uc2a4\ud2b8\ub9ac\ubc0d(Adaptive BitRate Streaming)\uc744 \uc18c\uac1c\ud558\uace0, \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ud574\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1c9e548d-8a8e-80a5-b5cb-fdccab887c9b\\" id=\\"1c9e548d-8a8e-80a5-b5cb-fdccab887c9b\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://github.com/facebook/react/releases/tag/v19.1.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/facebook/react/releases/tag/v19.1.0</a><p data-notion-block-id=\\"1cee548d-8a8e-8054-8963-c67e160239a1\\">\ucef4\ud3ec\ub10c\ud2b8 \uc2a4\ud0dd\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub294 <code>captureOwnerStack</code> API\uac00 \ud3ec\ud568\ub41c 19.1\ubc84\uc804\uc774 \ubc30\ud3ec\ub418\uc5c8\uc2b5\ub2c8\ub2e4. </p><a href=\\"https://animejs.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://animejs.com/</a><p data-notion-block-id=\\"1cbe548d-8a8e-80c4-81f2-c78d804178c3\\">\uc5ec\ub7ec\uac00\uc9c0 \uc560\ub2c8\uba54\uc774\uc158\uc744 \uc27d\uac8c \uad6c\ud604\ud560 \uc218\ub85d \ub3c4\uc640\uc8fc\ub294 anime.js\uac00 4\ubc84\uc804\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4. Web Animation API \ud5ec\ud37c, Engine API\u2026 \uc5ec\ub7ec\uac00\uc9c0\uac00 \ucd94\uac00\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://astro.build/blog/astro-560/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://astro.build/blog/astro-560/</a><p data-notion-block-id=\\"1cee548d-8a8e-80b5-b4e7-f97715a11de8\\">Cloudflare\uc5d0\uc11c\uc758 \ud65c\uc6a9\uc131\uc744 \ub192\uc778 Astro 5.6\ubc84\uc804\uc774 \ubc30\ud3ec\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p>"}')}}]);